import os
import subprocess

# List writable directories in root and common system locations
writable_dirs = []
for d in ['/tmp', '/var/tmp', '/dev/shm', '/run', '/mnt', '/media']:
    if os.path.isdir(d) and os.access(d, os.W_OK):
        writable_dirs.append(d)

# List processes with their command lines to check for privileged or interesting processes
try:
    ps_output = subprocess.check_output(['ps', 'aux'], text=True)
except Exception as e:
    ps_output = f'Failed to run ps command: {e}'

writable_dirs, ps_output[:2000]  # limit output length for safety

